<div class="section-actions"><p class="muted"><?= $e($organization['description']??'') ?></p><?php if($actor->role==='administrator'): ?><a class="button secondary" href="<?= $link('/organizations/'.$organization['id'].'/edit') ?>">Edit organization</a><?php endif; ?></div>
<section class="card organization-details"><h2>Organization details</h2><dl><?php foreach(['website'=>'Website','phone'=>'Phone','address'=>'Address','notes'=>'Notes'] as $field=>$label): ?><?php if(!empty($organization[$field])): ?><dt><?= $e($label) ?></dt><dd><?php if($field==='website'): ?><a href="<?= $e($organization[$field]) ?>" target="_blank" rel="noopener noreferrer"><?= $e($organization[$field]) ?></a><?php else: ?><?= nl2br($e($organization[$field])) ?><?php endif; ?></dd><?php endif; ?><?php endforeach; ?></dl><a class="button secondary" href="<?= $link('/organizations/'.$organization['id'].'/passwords') ?>">View passwords</a></section>
<div class="stats-grid"><?php foreach($counts as $type=>$count): ?><a class="card stat-card" href="<?= $link('/organizations/'.$organization['id'].'/'.$type) ?>"><span class="stat-value"><?= $e($count>=50?'50+':$count) ?></span><span><?= $e((['asset'=>'Configurations','article'=>'Documents','contact'=>'Contacts','location'=>'Locations'][$type])) ?></span><small>View documentation →</small></a><?php endforeach; ?></div>
<div class="two-columns"><?php foreach($recent as $type=>$items): ?><section class="card"><div class="card-heading"><h2><?= $e((['asset'=>'Configurations','article'=>'Documents','contact'=>'Contacts','location'=>'Locations'][$type])) ?></h2><a href="<?= $link('/organizations/'.$organization['id'].'/'.$type) ?>">View all</a></div><?php if(!$items): ?><p class="muted">No <?= $e($type) ?> documentation yet.</p><?php else: ?><ul class="record-links"><?php foreach($items as $r): ?><li><a href="<?= $link('/records/'.$r['id']) ?>"><?= $e($r['title']) ?></a><span class="badge"><?= $r['visibility']==='internal'?'Internal only':'Client visible' ?></span></li><?php endforeach; ?></ul><?php endif; ?></section><?php endforeach; ?></div>
<?php if($actor->role==='administrator'): ?><details class="card danger-zone"><summary>Archive organization</summary><p>Archiving hides this organization and its documentation. You can restore it later.</p><form method="post" action="<?= $link('/organizations/'.$organization['id'].'/archive') ?>" data-confirm="Archive this organization and hide its documentation?"><?= $csrf ?><button class="button danger">Archive organization</button></form></details><?php endif; ?>
